import { useId } from 'react';
import './ListWorkspace.css';
export type Item = { id: string; title: string };
export type ListState = { items: Item[] | null; pending: boolean; error: string | null };
export function ListWorkspace({ state, retry, create, open }: { state: ListState; retry: () => void; create: () => void; open: (id: string) => void }) {
 const id = useId();
 const { items, pending, error } = state;
 return <section className="list-workspace" aria-labelledby={id}>
 <header><h1 id={id}>Items</h1><button onClick={retry} disabled={pending}>Refresh</button></header>
 <p role="status">{pending ? (items === null ? 'Loading items…' : 'Refreshing items. Previous results remain available.') : ''}</p>
 {error && <div role="alert" className="workspace-error"><strong>Could not {items === null ? 'load' : 'refresh'} items.</strong><p>{error}</p>{items !== null && <p>Showing the last available results.</p>}<button onClick={retry} disabled={pending}>Try again</button></div>}
 <div aria-busy={pending}>
 {items === null ? (!pending && !error ? <p>Items have not loaded. <button onClick={retry}>Load items</button></p> : null)
 : items.length === 0 ? <div className="workspace-empty"><h2>No items yet</h2><p>Create an item to get started.</p><button onClick={create}>Create item</button></div>
 : <ul>{items.map(item => <li key={item.id}><button onClick={() => open(item.id)}>{item.title}</button></li>)}</ul>}
 </div></section>;
}
// Keep the last successful items in application state when starting or failing a refresh.
export function beginRefresh(state: ListState): ListState { return { ...state, pending: true, error: null }; }
export function loadSucceeded(items: Item[]): ListState { return { items, pending: false, error: null }; }
export function loadFailed(state: ListState, error: string): ListState { return { ...state, pending: false, error }; }
